// Regenerates src/utils/contentLanguageCharSets.js from OpenCC's tables.
// Run after upgrading opencc-js: node scripts/generate-content-language-charsets.mjs
import { writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildCharSets } from '../src/utils/contentLanguageCharSetDerivation.js';

export function renderCharSetsModule(charSets = buildCharSets()) {
  const line = (name, set) =>
    `export const ${name} =\n  '${[...set].sort().join('')}';\n`;
  return [
    '// Generated by scripts/generate-content-language-charsets.mjs; do not edit.',
    '// Each string holds single-code-point characters; read it as a Set.',
    line('JAPANESE_ONLY', charSets.japaneseOnly),
    line('SIMPLIFIED_ONLY', charSets.simplifiedOnly),
    line('TRADITIONAL_ONLY', charSets.traditionalOnly),
  ].join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const target = resolve(
    dirname(fileURLToPath(import.meta.url)),
    '../src/utils/contentLanguageCharSets.js',
  );
  writeFileSync(target, renderCharSetsModule());
  console.log(`wrote ${target}`);
}
